                                                                                                                                                                                                                                                                                  '<b>ряда '
                                                                                                                                                                                                                                                                                  'адмиралов</b> '
                                                                                                                                                                                                                                                                                  'другого '
                                                                                                                                                                                                                                                                                  'игрока. '
                                                                                                                                                                                                                                                                                  'Напротив '
                                                                                                                                                                                                                                                                                  'всегда '
